// Port of backend/app/core/fsm.py (the reference). Behaviour must stay identical: host tests replay golden
// traces generated by the Python implementation. Pure C++11, no Arduino headers.
#pragma once
#include <stdint.h>

namespace fsync {

struct Timing {
  uint32_t min_green_ms, yellow_ms, all_red_ms, max_green_ms, max_red_ms;
  uint32_t fallback_green_ms, command_valid_ms, backend_lost_ms;
};

enum Phase : uint8_t { PHASE_GREEN = 0, PHASE_YELLOW = 1, PHASE_ALL_RED = 2 };
const char* phase_name(Phase p);

struct Lamps { char a; char b; };   // each 'R' | 'Y' | 'G'

// At most one axis may be non-red (two-movement intersection: all movements conflict).
inline bool lamps_safe(Lamps l) { return !(l.a != 'R' && l.b != 'R'); }

struct DeviceState {
  Phase phase;
  char axis, next_axis;
  uint32_t elapsed_ms;
  Lamps lamps;
  bool backend_ok;
};

class SignalFsm {
 public:
  SignalFsm(const Timing& t, uint32_t now_ms);

  // Returns true if accepted. `reason` is always set: "ok" | "bad_target" | "bad_validity" | "stale_seq".
  bool receive_command(int64_t seq, char target, uint32_t valid_for_ms, uint32_t now_ms, const char** reason);
  void set_backend_ok(bool ok) { backend_ok_ = ok; }
  void tick(uint32_t now_ms);

  Lamps lamps() const;
  DeviceState state(uint32_t now_ms) const;
  Phase phase() const { return phase_; }
  char axis() const { return axis_; }

 private:
  void enter(Phase p, uint32_t now_ms) { phase_ = p; since_ = now_ms; }
  char desired(uint32_t now_ms) const;   // 0 = no valid command: hold

  Timing t_;
  Phase phase_;
  char axis_, next_axis_;
  uint32_t since_;
  bool backend_ok_;
  bool has_target_;
  char target_;
  uint32_t target_until_;
  int64_t last_seq_;
};

}  // namespace fsync
